SELECT *
FROM INSPECT_DETAIL
WHERE INSPECT_CODE = #{inspectRecordId}
  AND ASSET_ID = #{assetId}
  AND (INSPECT_STATE IN (4, 5))
ORDER BY TARGET_ITEM

SELECT COLLECT_CATEGORY
FROM ALARM_EVENT_TYPE
WHERE ID IN (
    SELECT EVENT_TYPE_ID
    FROM INSPECT_ASSET
    WHERE JOB_ID = #{jobId}
      AND ASSET_ID = #{assetId}
    GROUP BY EVENT_TYPE_ID
)
